import {STOPS,has,stage,passStatus,pendingAction} from './journey.mjs';
const button=(label,action,cls='primary')=>`<button type="button" class="${cls}" data-action="${action}">${label}</button>`;
export function passGraphic(s){const points=s.journey?.pass?.source||[];return `<svg viewBox="0 0 200 140" role="img" aria-label="Your repaired pass: each printed point has an equal-distance reflected partner"><rect x="1" y="1" width="198" height="138" rx="12" fill="#fff1c5" stroke="#bca58e"/><path d="M12 70H188" stroke="#c6a461" stroke-dasharray="5 4"/>${points.map((p,i)=>[1,-1].map(side=>`<circle cx="${20+p.x*16}" cy="${70-side*p.y*14}" r="5" fill="${['#d57b69','#69a89e','#a283b7'][i]}"/>`).join('')).join('')}</svg>`;}
export function opening(){return `<header class="hud"><div class="logo">FIND LUMI!<small>A REFLECTION JOURNEY</small></div>${button('Settings','settings','quiet')}</header><section class="opening-card"><p class="kicker">AFTER HOURS · THE MIRROR MUSEUM</p><h1>Find Lumi.<br>Leave together.</h1><p class="pip-line"><b>Pip:</b> “Lumi is safe with me in the Star Gallery. The normal visitor route is closed. Follow the exhibits to reach us.”</p><p>You are Maya. First, find a way past the workshop wall. Later, bring Lumi along the return route to the museum exit.</p><div class="journey-acts"><span>1 · Find a route</span><span>2 · Reach Lumi</span><span>3 · Leave together</span></div><p class="small">Six connected tasks. Learn each method before using it. There is no countdown.</p><div class="result-actions">${button('Find a way ahead →','begin-journey')}${button('See the museum map','map','quiet')}</div></section>`;}
export function mapPanel(s){return `<p class="kicker">MUSEUM ROUTE · ${stage(s).toUpperCase()}</p><h2>Find her. Leave together.</h2><p>The route runs through the exhibits to Lumi, then back to the exit. Each useful action changes this map.</p><ol class="route-map">${STOPS.map((stop,i)=>{const done=has(s,stop.flag),here=s.screen!=='opening'&&s.screen!=='about'&&s.screen!=='end'&&!s.bonus&&s.chapter===i+1;return `<li class="${done?'unlocked':''} ${here?'here':''}" ${here?'aria-current="step"':''}><span class="route-node">${done?'✓':i+1}</span><div><b>${stop.name}</b><small>${done?'Route secured':here?'Your current objective':'Ahead on the route'}</small>${here?`<p>${done?stop.reward:stop.goal}</p>`:''}${i===4?`<span class="map-person">${has(s,'reunited')?'Maya + Lumi are together':'Lumi + Pip · safe in the gallery'}</span>`:''}${i===5&&has(s,'escaped')?'<span class="map-person">Maya + Lumi · outside together</span>':''}</div></li>`;}).join('')}</ol><div class="inventory-card"><b>VISITOR PASS</b><p>${passStatus(s)}</p><small>${has(s,'pass-repaired')?'The pass is kept in your inventory. Its symmetric pattern is the courtyard gate’s access key.':'Its missing half is explicitly mirror-symmetric. Repair it in the paper studio.'}</small>${has(s,'pass-repaired')?passGraphic(s):''}</div><p class="small">This map shows your adventure progress. The shortest-path mathematics is used in individual flat-mirror light puzzles.</p>`;}
export function pendingPanel(s){const action=pendingAction(s);if(!action)return '';
 const copy={
 'insert-pass':['YOUR PASS IS READY','Use what you made.','The fold confirmed your reflected pattern. Insert the repaired visitor pass into the courtyard gate’s reader.','Insert my visitor pass →'],
 'reunite':['THE STAR GALLERY IS OPEN','“Mum, over here!”','Your two constructions lit the approach and opened the gallery gate. Walk through to Lumi and Pip.','Walk through to Lumi →'],
 'leave-together':['THE FINAL EXIT IS OPEN','Go home together.','Both return markers are lit and the exit receiver is active. Maya and Lumi can now walk out together.','Leave the museum together →']
 }[action];return `<section class="story-action" aria-labelledby="story-title"><p class="kicker">${copy[0]}</p><h2 id="story-title">${copy[1]}</h2><p>${copy[2]}</p>${action==='insert-pass'?`<div class="visitor-pass" role="img" aria-label="Repaired visitor pass with three matching reflected pairs"><b>MIRROR MUSEUM</b>${passGraphic(s)}<small>SYMMETRY VERIFIED</small></div>`:''}${button(copy[3],action)}</section>`;}
export const rewardLine=s=>s.bonus?'Your optional design works.':STOPS[s.chapter-1].reward;
